// Object keywords for all drafts.
// Every keyword self-guards on plain-object instances (not arrays, not null),
// mirroring Python jsonschema's `is_type(instance, "object")` checks.

import { makeError } from "../errors.mjs";

function isPlainObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function toRegExp(pattern) {
  // Python uses re.search (unanchored); JS RegExp.prototype.test is unanchored
  // too. An invalid pattern throws, just like Python's re.error crash.
  return new RegExp(pattern);
}

function properties(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  const errors = [];
  for (const [key, subschema] of Object.entries(value)) {
    if (key in instance) {
      errors.push(
        ...ctx.descend(instance[key], subschema, [key], ["properties", key]),
      );
    }
  }
  return errors;
}

function patternProperties(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  const errors = [];
  for (const [pattern, subschema] of Object.entries(value)) {
    const re = toRegExp(pattern);
    for (const [key, val] of Object.entries(instance)) {
      // re.search semantics: every matching (pattern, key) pair descends.
      if (re.test(key)) {
        errors.push(
          ...ctx.descend(val, subschema, [key], ["patternProperties", pattern]),
        );
      }
    }
  }
  return errors;
}

function findExtras(instance, schema) {
  const declared = isPlainObject(schema.properties)
    ? new Set(Object.keys(schema.properties))
    : new Set();
  const patterns = isPlainObject(schema.patternProperties)
    ? Object.keys(schema.patternProperties).map(toRegExp)
    : [];
  return Object.keys(instance).filter(
    (key) =>
      !declared.has(key) && !patterns.some((re) => re.test(key)),
  );
}

function additionalProperties(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  const extras = findExtras(instance, schema);
  if (extras.length === 0 || value === true) return [];
  if (value === false) {
    // Verified against the reference: a SINGLE error no matter how many
    // extra properties exist (jsonschema lists them all in one message).
    return [makeError([], ["additionalProperties"])];
  }
  const errors = [];
  for (const key of extras) {
    errors.push(
      ...ctx.descend(instance[key], value, [key], ["additionalProperties"]),
    );
  }
  return errors;
}

function required(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  if (!Array.isArray(value)) return [];
  const errors = [];
  for (const key of value) {
    if (!(key in instance)) {
      errors.push(makeError([], ["required"]));
    }
  }
  return errors;
}

function minProperties(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  if (Object.keys(instance).length < value) {
    return [makeError([], ["minProperties"])];
  }
  return [];
}

function maxProperties(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  if (Object.keys(instance).length > value) {
    return [makeError([], ["maxProperties"])];
  }
  return [];
}

function propertyNames(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  const errors = [];
  for (const key of Object.keys(instance)) {
    // Python descends with the KEY as the instance and adds nothing to the
    // instance path.
    errors.push(...ctx.descend(key, value, [], ["propertyNames"]));
  }
  return errors;
}

// drafts 4..2019 only; the engine omits this keyword for 2020.
function dependencies(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  const errors = [];
  for (const [key, dependency] of Object.entries(value)) {
    if (!(key in instance)) continue;
    if (Array.isArray(dependency)) {
      for (const each of dependency) {
        if (!(each in instance)) {
          errors.push(makeError([], ["dependencies", key]));
        }
      }
    } else {
      errors.push(...ctx.descend(instance, dependency, [], ["dependencies", key]));
    }
  }
  return errors;
}

function dependentRequired(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  const errors = [];
  for (const [key, dependency] of Object.entries(value)) {
    if (!(key in instance)) continue;
    for (const each of dependency) {
      if (!(each in instance)) {
        errors.push(makeError([], ["dependentRequired", key]));
      }
    }
  }
  return errors;
}

function dependentSchemas(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  const errors = [];
  for (const [key, subschema] of Object.entries(value)) {
    if (!(key in instance)) continue;
    errors.push(...ctx.descend(instance, subschema, [], ["dependentSchemas", key]));
  }
  return errors;
}

export const keywords = {
  properties,
  patternProperties,
  additionalProperties,
  required,
  minProperties,
  maxProperties,
  propertyNames,
  dependencies,
  dependentRequired,
  dependentSchemas,
};
